def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x - 1, y - 1)] = value

    # Initialize DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[(0, 0)]

    # Fill DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(i1 + 1):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N:
                    continue
                if (i1, j1) not in grid or (i2, j2) not in grid:
                    continue
                value = grid[(i1, j1)]
                if i1 != i2:
                    value += grid[(i2, j2)]
                max_prev = -float('inf')
                for di1, dj1 in [(-1, 0), (0, -1)]:
                    for di2, dj2 in [(-1, 0), (0, -1)]:
                        ni1, nj1 = i1 + di1, j1 + dj1
                        ni2, nj2 = i2 + di2, j2 + dj2
                        if 0 <= ni1 < N and 0 <= nj1 < N and 0 <= ni2 < N and 0 <= nj2 < N:
                            max_prev = max(max_prev, dp[ni1][nj1][nj2])
                dp[i1][j1][j2] = max(dp[i1][j1][j2], max_prev + value)

    return max(0, dp[N-1][N-1][N-1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Create a 4D DP table to store the maximum values collected by two paths
    dp = [[[[float('-inf')] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]

    # Initialize the starting point
    dp[0][0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(i + 1):
                for l in range(j + 1):
                    if dp[i][j][k][l] == float('-inf'):
                        continue

                    # Both paths move down
                    if i + 1 < N:
                        if k + 1 < N and l + 1 < N:
                            dp[i + 1][j + 1][k + 1][l + 1] = max(
                                dp[i + 1][j + 1][k + 1][l + 1],
                                dp[i][j][k][l] + grid[i + 1][j + 1] + grid[k + 1][l + 1] - (grid[i + 1][j + 1] if k + 1 == i + 1 and l + 1 == j + 1 else 0)
                            )

                    # Path 1 moves down, Path 2 moves right
                    if i + 1 < N and l < N:
                        dp[i + 1][j][k + 1][l] = max(
                            dp[i + 1][j][k + 1][l],
                            dp[i][j][k][l] + grid[i + 1][j] + grid[k + 1][l] - (grid[i + 1][j] if k + 1 == i + 1 and l == j else 0)
                        )

                    # Path 1 moves right, Path 2 moves down
                    if k < N and j + 1 < N:
                        dp[i][j + 1][k][l + 1] = max(
                            dp[i][j + 1][k][l + 1],
                            dp[i][j][k][l] + grid[i][j + 1] + grid[k][l + 1] - (grid[i][j + 1] if k == i and l + 1 == j + 1 else 0)
                        )

                    # Both paths move right
                    if j + 1 < N:
                        if l < N and k < N:
                            dp[i][j + 1][k][l + 1] = max(
                                dp[i][j + 1][k][l + 1],
                                dp[i][j][k][l] + grid[i][j + 1] + grid[k][l + 1] - (grid[i][j + 1] if k == i and l + 1 == j + 1 else 0)
                            )

    # The result is the maximum value collected by both paths reaching the bottom-right corner
    return max(dp[N - 1][N - 1][k][l] for k in range(N) for l in range(N))

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for easy access
    grid = defaultdict(int)
    for x, y, value in grid_values:
