        grid[(x-1, y-1)] = value

    # Initialize DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]

    # Base case
    dp[0][0][0] = grid[(0, 0)]

    # Fill DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(max(0, i1 + j1 - N + 1), min(i1 + j1 + 1, N)):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or (i1, j1) not in grid or (i2, j2) not in grid:
                    continue
                current_value = grid[(i1, j1)] + (grid[(i2, j2)] if (i1, j1) != (i2, j2) else 0)
                for pi1, pj1 in [(i1-1, j1), (i1, j1-1)]:
                    for pi2, pj2 in [(i2-1, j2), (i2, j2-1)]:
                        if pi1 >= 0 and pj1 >= 0 and pi2 >= 0 and pj2 >= 0:
                            dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[pi1][pj1][pi2] + current_value)

    return max(dp[N-1][N-1][i] for i in range(N))

