    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(min(i + j + 1, N)):
                l = i + j - k
                if l < 0 or l >= N:
                    continue
                # Move from (i-1, j) to (i, j) with first path and (k, l-1) to (k, l) with second path
                if i > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][j] + (grid[k][l] if j != l else 0))
                if i > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][j] + grid[k][l])
                if j > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[i][j] + (grid[k][l] if i != k else 0))
                if j > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[i][j] + grid[k][l])

    # The result is the maximum value collected by both paths reaching the bottom-right corner
    return max(0, dp[N-1][N-1][N-1])

