    def generate_numbers():
        numbers = []
        for i in range(1, 10):
            for j in range(1, 10):
                if j == i:
                    continue
                for k in range(1, 10):
                    if k == i or k == j:
                        continue
                    num = i * 100 + j * 10 + k
                    numbers.append(num)
        return numbers

    valid_combinations = []
    for num in generate_numbers():
