def cantor_numbering(N: int) -> str:
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer.")

    level = 1
    current = 0

    while current + level < N:
        current += level
        level += 1

    position_in_level = N - current - 1

    if level % 2 == 0:
        numerator = 1 + position_in_level
        denominator = level - position_in_level
    else:
        numerator = level - position_in_level
        denominator = 1 + position_in_level

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("N must be a positive integer.")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        # Even level, fractions go from bottom-left to top-right
        numerator = N
        denominator = level - N + 1
    else:
        # Odd level, fractions go from top-right to bottom-left
        numerator = level - N + 1
        denominator = N

    return f"{numerator}/{denominator}"

