def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if M < 2 or N < 2 or K < 0 or L < 0 or D < 0:
        raise ValueError("Invalid input dimensions or counts.")
    if any(len(pair) != 4 for pair in chatting_pairs):
        raise ValueError("Invalid chatting pairs format.")
    if any(x < 1 or x > M or y < 1 or y > N or p < 1 or p > M or q < 1 or q > N for x, y, p, q in chatting_pairs):
        raise ValueError("Chatting pairs out of bounds.")

    horizontal_separations = [0] * (M + 1)
    vertical_separations = [0] * (N + 1)

    for x, y, p, q in chatting_pairs:
        if x != p:  # chatting in the same column
            min_row, max_row = min(x, p), max(x, p)
            horizontal_separations[min_row] += 1
        if y != q:  # chatting in the same row
            min_col, max_col = min(y, q), max(y, q)
            vertical_separations[min_col] += 1

    # Find top K horizontal and L vertical separators
    best_horizontal_indices = sorted(range(1, M), key=lambda i: horizontal_separations[i], reverse=True)[:K]
    best_vertical_indices = sorted(range(1, N), key=lambda j: vertical_separations[j], reverse=True)[:L]

    return ' '.join(map(str, best_horizontal_indices)), ' '.join(map(str, best_vertical_indices))

