    if not all(isinstance(pair, tuple) and len(pair) == 4 for pair in chatting_pairs):
        raise ValueError("Chatting pairs must be provided as tuples of four integers.")

    row_separations = [0] * (M + 1)
    col_separations = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if not (1 <= Xi <= M and 1 <= Yi <= N and 1 <= Pi <= M and 1 <= Qi <= N):
            raise ValueError("Chatting pair positions are out of classroom bounds.")
        if Xi == Pi:
            if Yi < Qi:
                row_separations[Xi] += 1
            elif Qi < Yi:
                row_separations[Pi] += 1
        elif Yi == Qi:
            if Xi < Pi:
                col_separations[Yi] += 1
            elif Pi < Xi:
                col_separations[Qi] += 1

    best_row_indices = sorted(range(1, M + 1), key=lambda x: row_separations[x], reverse=True)[:K]
    best_col_indices = sorted(range(1, N + 1), key=lambda x: col_separations[x], reverse=True)[:L]

