def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from collections import defaultdict

    # Initialize counts for potential horizontal and vertical aisles
    horizontal_counts = defaultdict(int)
    vertical_counts = defaultdict(int)

    # Count how many chatting pairs can be separated by each potential aisle
    for (xi, yi), (pi, qi) in [((x1, y1), (x2, y2)) for (x1, y1, x2, y2) in chatting_pairs]:
        if xi == pi:
            # Same row, vertical aisle can separate them
            if yi < qi:
                vertical_counts[yi] += 1
            else:
                vertical_counts[qi] += 1
        elif yi == qi:
            # Same column, horizontal aisle can separate them
            if xi < pi:
                horizontal_counts[xi] += 1
            else:
                horizontal_counts[pi] += 1

    # Sort the potential aisles by the number of separated pairs in descending order
    sorted_horizontal = sorted(horizontal_counts.items(), key=lambda x: x[1], reverse=True)
    sorted_vertical = sorted(vertical_counts.items(), key=lambda x: x[1], reverse=True)

    # Select the top K horizontal and L vertical aisles
    selected_horizontal = [str(row) for row, count in sorted_horizontal[:K]]
    selected_vertical = [str(col) for col, count in sorted_vertical[:L]]

    # Return the results as space-separated strings
    return ' '.join(selected_horizontal), ' '.join(selected_vertical)

