def max_energy(beads):
    def merge_energy(i, j, beads, dp):
        if dp[i][j] != -1:
            return dp[i][j]
        if j == i + 1:
            dp[i][j] = 0
            return 0
        max_energy_val = 0
        for k in range(i + 1, j):
            max_energy_val = max(max_energy_val, merge_energy(i, k, beads, dp) + merge_energy(k, j, beads, dp) + beads[i] * beads[k] * beads[j])
        dp[i][j] = max_energy_val
        return max_energy_val

    if not beads or len(beads) < 3:
        return 0

    n = len(beads)
    beads = [0] + beads + [beads[0]]
    dp = [[-1] * (n + 2) for _ in range(n + 2)]
    return merge_energy(0, n + 1, beads, dp)

