    # Extend the beads array to simulate the circular nature
    beads = beads + beads

    # dp[i][j] will store the max energy we can get from merging beads[i+1] to beads[j-1]
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    # We need to consider all chains of length 3 to n
    for length in range(3, n + 1):
        for i in range(n):
            j = i + length
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    # The result is the maximum energy we can get by merging beads[0] to beads[n-1]
    return max(dp[i][i + n] for i in range(n))

