    def merge_energy(i, j):
        if i == j:
            return 0
        max_energy = 0
        for k in range(i, j):
            current_energy = beads[i] * beads[k + 1] * beads[j + 1]
            energy = merge_energy(i, k) + merge_energy(k + 1, j) + current_energy
            max_energy = max(max_energy, energy)
        return max_energy

    n = len(beads)
    beads.append(beads[0])  # Make the necklace circular by appending the first bead to the end
    memo = {}

    def dp(i, j):
        if i >= j:
            return 0
        if (i, j) in memo:
            return memo[(i, j)]
        result = max_energy(i, j)
        memo[(i, j)] = result
        return result

    return dp(0, n - 1)

