    n = len(beads)
    # Extend the beads to simulate the circular nature
    beads = beads + beads

    # dp[i][j] will store the max energy released merging beads from index i to j in the original list
    dp = [[0] * n for _ in range(n)]

    # Iterate over all chain lengths from 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j] + beads[i] * beads[k + 1] * beads[j + 1])

    return dp[0][n - 1]

