def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    if k == 0:
        return 1 if n == 0 else 0

    def helper(n, k, x, memo):
        if (n, k, x) in memo:
            return memo[(n, k, x)]
        if n < k * x or k == 0:
            return 0
        if k == 1:
            return 1 if n >= x else 0

        # Include at least one part of size x and partition the rest
        count_with_x = helper(n - x, k - 1, x, memo)
        # Do not include any part of size x and partition the rest with increased minimum size
        count_without_x = helper(n, k, x + 1, memo) if n > k * (x + 1) else 0

        memo[(n, k, x)] = count_with_x + count_without_x
        return memo[(n, k, x)]

    return helper(n, k, x, {})

