def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation map from the rules
    transform_map = defaultdict(list)
    for x, y in rules:
        transform_map[x].append(y)

    # Convert the number to a list of digits
    original_digits = list(str(n))
    queue = deque([original_digits])
    visited = set()
    visited.add(tuple(original_digits))

    while queue:
        current_digits = queue.popleft()

        # Generate all possible transformations for the current number
        for i, digit in enumerate(current_digits):
            if int(digit) in transform_map:
                for new_digit in transform_map[int(digit)]:
                    new_digits = current_digits[:]
                    new_digits[i] = str(new_digit)
                    new_number_tuple = tuple(new_digits)
                    if new_number_tuple not in visited:
                        visited.add(new_number_tuple)
                        queue.append(new_digits)

    # Return the count of unique numbers generated
    return len(visited)

