def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        is_liar = participant in liar_count
        for statement in participant_statements:
            # Ignore statements about the day of the week
            if statement.upper() in days_of_week or any(day.upper() in statement.upper() for day in days_of_week):
                continue

            # Check statements about guilt
            if "guilty" in statement.lower():
                target = statement.split()[0].upper()
                if target == scenario:
                    # If the statement is "X is guilty" and X is the scenario, it must be consistent with liar status
                    if is_liar and statement.lower().startswith(f"{scenario.lower()} is guilty"):
                        return False
                    elif not is_liar and not statement.lower().startswith(f"{scenario.lower()} is guilty"):
                        return False
                else:
                    # If the statement is about someone else's guilt, it should not contradict the scenario
                    if is_liar and statement.lower().startswith(f"{target.lower()} is guilty"):
                        continue
                    elif not is_liar and not statement.lower().startswith(f"{target.lower()} is guilty"):
                        continue
            elif "not guilty" in statement.lower():
                target = statement.split()[0].upper()
                if target == scenario:
                    # If the statement is "X is not guilty" and X is the scenario, it must be consistent with liar status
                    if is_liar and statement.lower().startswith(f"{scenario.lower()} is not guilty"):
                        return False
                    elif not is_liar and not statement.lower().startswith(f"{scenario.lower()} is not guilty"):
                        return False
    return True

