def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("All input values must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items n must match the length of the volumes list.")

    # Initialize DP array
    dp = [0] * (V + 1)

    # Fill the DP array
    for volume in volumes:
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    # The maximum volume that can be packed into the box
    max_occupied_volume = max(dp)

    # The minimum remaining space
    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("Capacity and volumes must be non-negative integers.")
    if n != len(volumes):
        raise ValueError("The number of items n must match the length of the volumes list.")

    # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (empty subset)

    # Fill the DP array
    for v in volumes:
        # Traverse backwards to avoid using the same item multiple times
        for j in range(V, v - 1, -1):
            if dp[j - v]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = max(i for i, can_form in enumerate(dp) if can_form)

    # The minimum remaining space is the total capacity minus the maximum achievable volume
    return V - max_achievable_volume

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # There's one way to arrange 0 pots (by choosing none)
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]  # Exclude the ith type
            for k in range(1, min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD  # Include the ith type with k pots

    return dp[n][m]

