        raise ValueError("The length of the prices list must be equal to the number of souvenirs `n`.")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    # The recursive relation for the double-disc Hanoi problem is:
    # moves(n) = 2 * moves(n-1) + 2
    # Base case: moves(1) = 2

    moves = 2  # Base case for n=1
    for i in range(2, n + 1):
        moves = 2 * moves + 2

    return moves

