def total_smoked_cigarettes(n, k):
    if n <= 0 or k <= 1:
        raise ValueError("Initial number of cigarettes must be greater than 0 and butts needed for an exchange must be greater than 1.")

    total_smoked = n
    butts = n

    while butts >= k:
        new_cigarettes = butts // k
        total_smoked += new_cigarettes
        butts = butts % k + new_cigarettes

    return total_smoked

